$:node <<'NODE'

const fs=require('fs'),path=require('path'),assert=require('assert');
const root='Tasks', completed=path.join(root,'TasksCompleted'), queue=path.join(root,'User Prompt Task Queue');
const read=p=>JSON.parse(fs.readFileSync(p,'utf8'));
const write=(p,x)=>fs.writeFileSync(p,JSON.stringify(x,null,2)+'\n');
const ids=['1794192853','1794193447','1794193968'];
const tasks=ids.map(id=>read(path.join(queue,'user-prompt-task-'+id+'.json')));
assert.deepStrictEqual(tasks.map(t=>t.task_type),['custom_instruction_revision','account_custom_instruction_wrapper_design','conversation_analytics_end_of_turn_append_rule']);
const template=read('conversations/conversation-record.template.json');
assert.strictEqual(template.template_id,'terminals.conversation-record');
assert.strictEqual(template.template_version,'1.0.0');
const revision=read(path.join(completed,'user-prompt-task-1794192853-revision.json'));
assert.strictEqual(revision.requirement_mapping.length,5);
assert(revision.replacement_instruction.includes('precise limitation'));
const previousWrapper=read(path.join(completed,'user-prompt-task-1794193447-wrapper.json'));
const originalGroup=previousWrapper[0];
assert(Array.isArray(originalGroup)&&originalGroup.length>=2);
assert(originalGroup[0].startsWith('Strict Adherence to User-Defined Scope'));
const analytics=read(path.join(completed,'user-prompt-task-1794193968-rule.json'));
assert(Array.isArray(analytics)&&analytics.length===2);
const rule=analytics[1];
assert.strictEqual(rule.template.template_id,template.template_id);
assert.strictEqual(rule.template.template_version,template.template_version);
assert.strictEqual(rule.template.path,'conversations/conversation-record.template.json');
assert.strictEqual(rule.destination.format,'JSON array');
assert(rule.append.atomicity.includes('compare-and-swap'));
const groupInterpretation='Final group element: interpretation instructions for this single-subject array; index 0 defines its subject and scope, indexes 1 through length-2 contain rules. Explicit local interpretation overrides conflicting outer-array interpretation only inside this group.';
const scopeGroup=[...originalGroup,groupInterpretation];
const analyticsGroup=[analytics[0],rule,groupInterpretation];
const outerInterpretation='Final outer element: interpretation instructions for this wrapper. Every preceding element is either an individual ad hoc rule or a single-subject grouped-rule array. Insert each new standalone ad hoc rule at outer index 0, shifting existing indices; preserve the final interpretation element. In each group, index 0 defines subject/scope, the last element defines local interpretation, and intermediate elements are rules. Explicit local interpretation overrides the outer interpretation only within that group. Preserve all prior instruction contents and scopes.';
const wrapper=[analyticsGroup,scopeGroup,outerInterpretation];
const validate=w=>{
 assert(Array.isArray(w)&&typeof w.at(-1)==='string');
 for(const group of w.slice(0,-1)){
  assert(Array.isArray(group)&&group.length>=3);
  assert(typeof group[0]==='string'&&group[0].length>0);
  assert(typeof group.at(-1)==='string'&&group.at(-1).includes('interpretation'));
 }
 assert.deepStrictEqual(w[1].slice(0,-1),originalGroup);
 assert.deepStrictEqual(w[0][1],rule);
};
validate(wrapper);
write(path.join(completed,'user-prompt-task-1794193447-wrapper.json'),wrapper);
write(path.join(completed,'user-prompt-task-1794193968-rule.json'),analyticsGroup);
const spec=[
'# Account custom-instruction wrapper — Task 1794193447','',
'## Structure',
'The wrapper is a JSON array. Each outer element except the final element is either a standalone ad hoc rule or a single-subject grouped array. The final outer element specifies interpretation rules for that outer array.','',
'Each grouped array has an index-0 entry defining its one subject and scope, rule entries at indexes 1 through length-2, and an interpretation entry at its final index. A group final element is reserved and is never an ordinary rule.','',
'## Ordering and insertion',
'Standalone ad hoc rules are newest-first: insert a new rule at index 0 of its applicable ad hoc array, shifting preexisting indices by +1 without displacing reserved structural entries. Insert subject-group rules before the reserved final local interpretation element.','',
'## Local precedence',
'The group index-0 scope and final local interpretation govern only that subject. Explicit local interpretation wins over conflicting outer interpretation only within that group.','',
'## Artifacts',
'Tasks/TasksCompleted/user-prompt-task-1794193447-wrapper.json contains the full prior scope instruction and the conversation-analytics rule as separate single-subject groups. Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json is the standalone analytics group. Tasks/TasksCompleted/user-prompt-task-1794192853-revision.json contains the proposed compact scope instruction.','',
'## Validation',
'- Root and each nested group are valid JSON arrays.',
'- The root final index and every group final index contain interpretation instructions.',
'- Each group index 0 specifies exactly one subject and scope; rule elements are between first and last.',
'- New standalone ad hoc rules are inserted at their applicable array index 0, preserving interpretation positions.',
'- Group-local overrides are confined to the group.',
'- Source account scope instructions remain substantively preserved.',
'- The analytics rule references terminals.conversation-record v1.0.0 at conversations/conversation-record.template.json.',
'- These artifacts do not claim account setting activation or an installed end-of-turn callback.','',
'## Source',
'Tasks/TasksCompleted/user-prompt-task-1794193447.json. This document corrects the previous contradiction concerning nested final-index semantics.',''
].join('\n');
fs.writeFileSync(path.join(completed,'user-prompt-task-1794193447-spec.md'),spec);
for(let i=0;i<ids.length;i++){
 const id=ids[i],t=tasks[i];
 t.status='completed';
 t.completed_at_utc=new Date().toISOString();
 t.completion={kind:'design_deliverable',activation:'not_performed',files:id==='1794192853'?['Tasks/TasksCompleted/user-prompt-task-1794192853-revision.json']:id==='1794193447'?['Tasks/TasksCompleted/user-prompt-task-1794193447-wrapper.json','Tasks/TasksCompleted/user-prompt-task-1794193447-spec.md']:['Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json','Tasks/TasksCompleted/user-prompt-task-1794193447-wrapper.json']};
 write(path.join(completed,'user-prompt-task-'+id+'.json'),t);
 fs.unlinkSync(path.join(queue,'user-prompt-task-'+id+'.json'));
}
const manifest={
 schema:'terminals.custom-instruction-design-completion.v1',
 completed_at_utc:new Date().toISOString(),
 tasks:ids.map(id=>({id,task_path:'Tasks/TasksCompleted/user-prompt-task-'+id+'.json',status:'completed',kind:'design_deliverable'})),
 artifacts:['Tasks/TasksCompleted/user-prompt-task-1794192853-revision.json','Tasks/TasksCompleted/user-prompt-task-1794193447-wrapper.json','Tasks/TasksCompleted/user-prompt-task-1794193447-spec.md','Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json'],
 verification:{template_id:template.template_id,template_version:template.template_version,template_path:'conversations/conversation-record.template.json',scope_preserved:true,nested_final_interpretation_present:true,analytics_record_append_contract_specified:true},
 activation:{account_custom_instructions:'not_updated',end_of_turn_hook:'not_installed',persistent_analytics_appends:'not_started',reason:'The queued deliverables were rule and wrapper designs, not activation of ChatGPT settings or deployment of a runtime callback.'},
 other_queued_tasks:'unchanged'
};
write(path.join(completed,'custom-instruction-task-completion.json'),manifest);
assert.strictEqual(read(path.join(completed,'custom-instruction-task-completion.json')).tasks.length,3);
validate(read(path.join(completed,'user-prompt-task-1794193447-wrapper.json')));
for(const id of ids){
 assert(!fs.existsSync(path.join(queue,'user-prompt-task-'+id+'.json')));
 assert.strictEqual(read(path.join(completed,'user-prompt-task-'+id+'.json')).status,'completed');
}
console.log('CUSTOM_INSTRUCTION_TASKS_COMPLETED',ids.join(','));
console.log('VALIDATION_PASSED');
console.log('NON_ACTIVATION_ASSERTED');

NODE
git add -- Tasks && git commit -m 'Complete custom-instruction design tasks and reconcile wrapper semantics' && git push origin HEAD:main && git status --short && git rev-parse HEAD
